for (const item of $input.all()) {

  let title = item.json["Job Title"] || "";
  let company = item.json["Company Name"] || "";
  title = title.trim().replace(/\s+/g, " ").toLowerCase();
  item.json.normalizedTitle = title;
  company = company.trim().replace(/\s+/g, " ").toLowerCase();
  item.json.normalizedCompanyName = company;
}
return $input.all();

const seen = new Map(); 

for (const item of $input.all()) {
  const key = `${item.json.normalizedTitle}|${item.json.normalizedCompanyName}`;
  const id = item.json["#"]; 

  if (!seen.has(key)) {
    seen.set(key, {
      'Job Title': item.json["Job Title"],
      'Company Name': item.json["Company Name"],
      normalizedTitle: item.json.normalizedTitle,
      normalizedCompanyName: item.json.normalizedCompanyName,
      rowIds: [id]
    });
  } else {

    seen.get(key).rowIds.push(id);
  }
}

return Array.from(seen.values()).map(data => ({ json: data }));

const items = $input.all();
const finalItems = [];

for (const item of items) {
  const text = item.json.content.parts[0].text;
  let contacts = [];

  try {
    contacts = JSON.parse(text);
  } catch (e) {
    // Handle JSON parsing errors if needed
  }

  // Flatten the array so every contact becomes its own n8n item
  for (const contact of contacts) {
    finalItems.push({
      json: {
        "#": contact["#"], // Maps the AI's "id" field straight to your row column
        "Function": contact.function || "Unknown",
        "Seniority": contact.seniority || "Unknown",
        "Confidence Score": contact.confidence || 0.00
      }
    });
  }
}

return finalItems;

const settings = $('Global Settings').first().json;

const SERIAL_NUMBER_COLUMN = settings["Serial Number Column Name"] || "#";
const JOB_TITLE_COLUMN = settings["Job Title Column Name"] || "Job Title";
const COMPANY_NAME_COLUMN = settings["Company Name Column Name"] || "Company Name";
const FUNCTION_COLUMN = settings["Function Column Name"] || "Function";
const SENIORITY_COLUMN = settings["Seniority Column Name"] || "Seniority";
const CONFIDENCE_COLUMN = settings["Confidence Score Column Name"] || "Confidence Score";    


return $input.all().map(item => ({
  json: {
    ...item.json,

    // Standard names used by the workflow
    "#": item.json[SERIAL_NUMBER_COLUMN],
    "Job Title": item.json[JOB_TITLE_COLUMN],
    "Company Name": item.json[COMPANY_NAME_COLUMN],
    "Function": item.json[FUNCTION_COLUMN],
    "Seniority": item.json[SENIORITY_COLUMN],
    "Confidence Score": item.json[CONFIDENCE_COLUMN],
  }
}));

const contacts = $input.all().map(item => ({
  "#": item.json.rowIds,
  "Job Title": item.json["Job Title"],
  "Company Name": item.json["Company Name"],
}));

return [
  {
    json: {
      contacts
    }
  }
];
